<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {ownerSession,clearOwnerSession} from '../../services/owner-session.js'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createCommunityQuestionApi,questionRoute,QUESTION_CATEGORIES,CASE_STATES,SERVICE_STATES,validQuestionText} from '../../services/community-questions.js'
import {createCommunityQuestionRecovery,pendingQuestion,createQuestionConfirmation} from '../../services/community-question-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const role=ref(''),id=ref(0),text=ref(''),consent=ref(false),state=reactive(initialDiagnosisState()),confirmation=reactive({prompt:null}),preview=ref(null),api=createCommunityQuestionApi(),token=()=>role.value==='owner'?ownerSession.accessToken:role.value==='admin'?operatorToken():'',actor=()=>role.value==='owner'?ownerSession.actorId:operatorSession.actorId,allowed=()=>id.value>0&&(role.value==='owner'||role.value==='admin'&&operatorSession.canCommunityAnswer)
const recovery=createCommunityQuestionRecovery({actor,role:()=>role.value,scope:()=>`case:${id.value}`}),gate=createQuestionConfirmation({state:confirmation,preview:()=>preview.value}),blocked=()=>state.busy||state.retry||state.kind==='storage'
async function load(t,p){const detail=await api.detail(t,role.value,id.value,p);let context=null;if(role.value==='owner')try{context=await api.context(t)}catch(e){if(['unauthorized','forbidden','missing'].includes(e.kind))throw e}return {detail,context}}
const flow=createAsyncDiagnosisFlow({state,token,allowed,scope:()=>`${role.value}:${actor()}:${id.value}`,load,write:(t,a,n,b,k)=>api.write(t,role.value,a,n,b,k),newKey:imageRequestKey,recovery,confirm:gate.ask,onWritten:clearForm})
let visible=false
function clearForm(){text.value='';consent.value=false;preview.value=null}
function reset(){gate.cancel();flow.reset();clearForm()}
function login(){if(role.value==='owner'){clearOwnerSession();uni.navigateTo({url:'/pages/owner/index'})}else{clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}}
function send(){if(blocked())return;const c=state.data?.detail.case,ctx=state.data?.context;if(!c||c.status==='CLOSED'||!validQuestionText(text.value.trim())||role.value==='admin'&&c.status!=='PROCESSING'){state.message='请核对当前记录状态并输入1至2000字。';return}const b={expected_revision:c.revision,message:text.value.trim()};if(role.value==='owner'){if(!ctx?.accepting||!consent.value){state.message='请核对当前受理并确认本次文字用途。';return}Object.assign(b,{policy_id:ctx.policy.id,policy_revision:ctx.policy.revision,consent:true})}const v=state.data.detail.vehicle;preview.value={title:role.value==='owner'?'确认补充私有问题':'确认提交私有答复',lines:[`问答 ${id.value} · 当前版本 ${c.revision}`,`原提交车型：${v.brand||''} ${v.series||''} ${v.year||''} ${v.config_name||''}`,'仅原提问者与当前获派人员可见；新增文字仍由服务器核验当前权限。',b.message]};flow.save(role.value==='owner'?'message':'reply',id.value,b)}
function close(){if(blocked())return;const c=state.data?.detail.case;if(!c||c.status==='CLOSED')return;preview.value={title:'确认关闭私有问答',lines:[`问答 ${id.value} · 当前版本 ${c.revision}`,'关闭后不能继续追加或答复，既有私有内容按原权限保留。']};flow.save('close',id.value,{expected_revision:c.revision})}
watch(()=>[token(),actor(),allowed(),role.value,id.value],()=>{reset();if(visible&&token()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){gate.cancel();clearForm()}},{flush:'sync'})
onLoad(q=>{const parsed=questionRoute(q||{});role.value=parsed?.role||'';id.value=parsed?.id||0});onShow(()=>{visible=true;if(token()&&allowed())flow.load()});function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">私有问题与运营答复</text><text>非实时；仅原提问者和当前获派且有独立处理权限的人员可读正文。</text><text v-if="!role||!id">问答入口参数无效。</text><text v-else-if="!allowed()">需要独立问答处理权限及当前分配。</text><button v-if="role&&!token()" @tap="login">登录当前身份</button><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><QuestionRecovery v-if="role&&id" :state="state" :flow="flow" :pending="pendingQuestion(recovery)"/><button :disabled="state.busy" @tap="flow.load(state.page)">重新核验权限与记录</button><template v-if="state.data"><view class="reservation-panel"><text>问答 {{id}} · {{CASE_STATES[state.data.detail.case.status]}} · {{QUESTION_CATEGORIES[state.data.detail.category]}}</text><text>原提交车型：{{state.data.detail.vehicle.brand}} {{state.data.detail.vehicle.series}} {{state.data.detail.vehicle.year}} {{state.data.detail.vehicle.config_name}}</text></view><view v-for="m in state.data.detail.messages.items" :key="m.message_id" class="reservation-panel"><text>{{m.sender==='OWNER'?'提问车主文字':'运营私有答复'}} · {{displayTime(m.created_at)}}</text><text class="question-text">{{m.body}}</text></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页文字</button><button v-if="state.page*20<state.data.detail.messages.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页文字</button><template v-if="state.data.detail.case.status!=='CLOSED'"><text v-if="role==='owner'">{{state.data.context?SERVICE_STATES[state.data.context.state]:'受理暂不可读取；仍可查看历史或关闭。'}}</text><template v-if="role==='owner'?state.data.context?.accepting:state.data.detail.case.status==='PROCESSING'"><textarea v-model="text" maxlength="4000" :disabled="blocked()" :placeholder="role==='owner'?'主动补充本次问题，最多2000字':'填写本次私有答复，最多2000字'"/><checkbox-group v-if="role==='owner'" @change="consent=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="consent" :disabled="blocked()"/>确认本次文字用于私有运营答复</label></checkbox-group><button :disabled="blocked()" @tap="send">预览并确认文字</button></template><button :disabled="blocked()" @tap="close">预览关闭本次问答</button></template></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
<style scoped>.question-text{white-space:pre-wrap;overflow-wrap:anywhere}</style>
